using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

// Configure the OpenAI-backed chat client through MEAI
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notebook>();
builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchService>();

var app = builder.Build();
await app.RunAsync();

// ---------------------------------------------------------------------------
// Hosted service that drives the agent
// ---------------------------------------------------------------------------
sealed class ResearchService(
    IChatClient chatClient,
    ResearchTools tools,
    Notebook notebook,
    IHostApplicationLifetime lifetime) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════╗");
        Console.WriteLine("║       🔍  Research Agent  🔍        ║");
        Console.WriteLine("╚══════════════════════════════════════╝");
        Console.WriteLine();

        Console.Write("Enter a research topic (or 'quit' to exit): ");
        var topic = Console.ReadLine()?.Trim();

        if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        {
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        // Build the agent with tools
        var agent = new ChatClientAgent(chatClient, $"""
            You are a thorough research agent. Your job is to research the topic
            the user provides by following these steps:

            1. Use the WebSearch tool to search for information about the topic.
               Make 2-3 searches with different, targeted queries to get broad coverage.
            2. After each search, use the SaveNote tool to record the most important
               findings — include key facts, data points, and source URLs.
            3. After you have gathered enough notes, use the GetNotes tool to review
               everything you have collected.
            4. Produce a final, well-structured summary of your research with sections
               for key findings, details, and sources.

            Be thorough but concise. Focus on factual, well-sourced information.
            """)
        {
            Name = "ResearchAgent",
            Tools = [.. AIFunctionFactory.Create(tools)],
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
        };

        var options = new AgentInvokeOptions { MaximumIterations = 15 };

        try
        {
            await foreach (var message in agent.InvokeStreamingAsync(history, options, stoppingToken))
            {
                if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
                {
                    Console.Write(message.Text);
                }
            }

            Console.WriteLine("\n\n--- Notes collected during research ---");
            foreach (var (i, note) in notebook.Notes.Select((n, i) => (i, n)))
            {
                Console.WriteLine($"  [{i + 1}] {note}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"\nError during research: {ex.Message}");
        }

        Console.WriteLine();
        lifetime.StopApplication();
    }
}

// ---------------------------------------------------------------------------
// Tools exposed to the agent
// ---------------------------------------------------------------------------
sealed class ResearchTools(Notebook notebook)
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a summary of search results.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use the DuckDuckGo Lite HTML endpoint (no API key required)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encodedQuery}";

            var html = await Http.GetStringAsync(url, cancellationToken);
            var results = ParseDuckDuckGoResults(html);

            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            return $"Search results for '{query}':\n" +
                   string.Join("\n", results.Select((r, i) => $"{i + 1}. {r}"));
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Save a research note for later reference. Use this to record important findings.")]
    public string SaveNote(
        [Description("The note content to save — include key facts and source URLs")] string note)
    {
        notebook.Notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({notebook.Notes.Count} total)");
        return $"Note saved. You now have {notebook.Notes.Count} note(s).";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetNotes()
    {
        if (notebook.Notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return "Saved notes:\n" +
               string.Join("\n", notebook.Notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    private static List<string> ParseDuckDuckGoResults(string html)
    {
        var results = new List<string>();
        var span = html.AsSpan();

        // Extract text snippets from result table rows in DuckDuckGo Lite
        const string snippetStart = "<td class=\"result-snippet\">";
        const string linkStart = "<a rel=\"nofollow\" href=\"";

        var pos = 0;
        while (pos < span.Length && results.Count < 8)
        {
            var snippetIdx = html.IndexOf(snippetStart, pos, StringComparison.Ordinal);
            if (snippetIdx < 0) break;

            var contentStart = snippetIdx + snippetStart.Length;
            var contentEnd = html.IndexOf("</td>", contentStart, StringComparison.Ordinal);
            if (contentEnd < 0) break;

            var snippet = StripHtml(html[contentStart..contentEnd]).Trim();

            // Look backwards for the link
            var linkIdx = html.LastIndexOf(linkStart, snippetIdx, StringComparison.Ordinal);
            var url = "";
            if (linkIdx >= 0)
            {
                var urlStart = linkIdx + linkStart.Length;
                var urlEnd = html.IndexOf('"', urlStart);
                if (urlEnd > urlStart)
                {
                    url = html[urlStart..urlEnd];
                }
            }

            if (!string.IsNullOrWhiteSpace(snippet))
            {
                results.Add(string.IsNullOrEmpty(url) ? snippet : $"{snippet} (Source: {url})");
            }

            pos = contentEnd + 5;
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var result = new System.Text.StringBuilder(html.Length);
        var inTag = false;
        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) result.Append(c);
        }
        return System.Net.WebUtility.HtmlDecode(result.ToString());
    }
}

// ---------------------------------------------------------------------------
// Shared notebook for storing research notes
// ---------------------------------------------------------------------------
sealed class Notebook
{
    public List<string> Notes { get; } = [];
}

