 sealed class ResearchTools(Notebook notebook)
 {
     private static readonly HttpClient Http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "text/html" },
         },
         Timeout = TimeSpan.FromSeconds(15),
     };

     [Description("Search the web for information on a query. Returns a summary of search results.")]
     public async Task<string> WebSearch(
         [Description("The search query string")] string query,
         CancellationToken cancellationToken = default)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         try
         {
             // Use the DuckDuckGo Lite HTML endpoint (no API key required)
             var encodedQuery = Uri.EscapeDataString(query);
             var url = $"https://lite.duckduckgo.com/lite/?q={encodedQuery}";

             var html = await Http.GetStringAsync(url, cancellationToken);
             var results = ParseDuckDuckGoResults(html);

             if (results.Count == 0)
             {
                 return $"No results found for '{query}'.";
             }

             return $"Search results for '{query}':\n" +
                    string.Join("\n", results.Select((r, i) => $"{i + 1}. {r}"));
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}";
         }
     }

     [Description("Save a research note for later reference. Use this to record important findings.")]
     public string SaveNote(
         [Description("The note content to save — include key facts and source URLs")] string note)
     {
         notebook.Notes.Add(note);
         Console.WriteLine($"  📝 Note saved ({notebook.Notes.Count} total)");
         return $"Note saved. You now have {notebook.Notes.Count} note(s).";
     }

     [Description("Retrieve all previously saved research notes.")]
     public string GetNotes()
     {
         if (notebook.Notes.Count == 0)
         {
             return "No notes saved yet.";
         }

         return "Saved notes:\n" +
                string.Join("\n", notebook.Notes.Select((n, i) => $"[{i + 1}] {n}"));
     }

     private static List<string> ParseDuckDuckGoResults(string html)
     {
         var results = new List<string>();
         var span = html.AsSpan();

         // Extract text snippets from result table rows in DuckDuckGo Lite
         const string snippetStart = "<td class=\"result-snippet\">";
         const string linkStart = "<a rel=\"nofollow\" href=\"";

         var pos = 0;
         while (pos < span.Length && results.Count < 8)
         {
             var snippetIdx = html.IndexOf(snippetStart, pos, StringComparison.Ordinal);
             if (snippetIdx < 0) break;

             var contentStart = snippetIdx + snippetStart.Length;
             var contentEnd = html.IndexOf("</td>", contentStart, StringComparison.Ordinal);
             if (contentEnd < 0) break;

             var snippet = StripHtml(html[contentStart..contentEnd]).Trim();

             // Look backwards for the link
             var linkIdx = html.LastIndexOf(linkStart, snippetIdx, StringComparison.Ordinal);
             var url = "";
             if (linkIdx >= 0)
             {
                 var urlStart = linkIdx + linkStart.Length;
                 var urlEnd = html.IndexOf('"', urlStart);
                 if (urlEnd > urlStart)
                 {
                     url = html[urlStart..urlEnd];
                 }
             }

             if (!string.IsNullOrWhiteSpace(snippet))
             {
                 results.Add(string.IsNullOrEmpty(url) ? snippet : $"{snippet} (Source: {url})");
             }

             pos = contentEnd + 5;
         }

         return results;
     }

     private static string StripHtml(string html)
     {
         var result = new System.Text.StringBuilder(html.Length);
         var inTag = false;
         foreach (var c in html)
         {
             if (c == '<') { inTag = true; continue; }
             if (c == '>') { inTag = false; continue; }
             if (!inTag) result.Append(c);
         }
         return System.Net.WebUtility.HtmlDecode(result.ToString());
     }
 }

